CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_findings_sla_overdue ON findings (tenant_id, sla_deadline) WHERE (((sla_status)::text <> ALL ((ARRAY['breached'::character varying, 'not_applicable'::character varying])::text[])) AND ((status)::text <> ALL ((ARRAY['closed'::character varying, 'resolved'::character varying, 'false_positive'::character varying, 'verified'::character varying])::text[])));
